-- Extend the concept graph; retain existing questions and learner attempts.
INSERT INTO concepts (name)
VALUES ('Interprocess Communication'), ('Synchronization'), ('Deadlock'), ('Memory Management')
ON CONFLICT (name) DO NOTHING;

INSERT INTO concept_prerequisites (concept_id, prerequisite_id)
SELECT dependent.id, prerequisite.id
FROM (VALUES
    ('Interprocess Communication', 'Processes'),
    ('Synchronization', 'Threads'),
    ('Deadlock', 'Synchronization'),
    ('Memory Management', 'Processes')
) AS edge(dependent_name, prerequisite_name)
JOIN concepts dependent ON dependent.name = edge.dependent_name
JOIN concepts prerequisite ON prerequisite.name = edge.prerequisite_name
ON CONFLICT DO NOTHING;

INSERT INTO questions (prompt, options, correct_option_id, explanation, concept_id)
SELECT seed.prompt, seed.options::jsonb, seed.answer, seed.explanation, c.id
FROM (VALUES
    ('Why do processes commonly need an interprocess communication mechanism to exchange data?',
     '{"A":"Separate process address spaces do not automatically expose private variables to each other","B":"Processes cannot use system calls","C":"Every process runs on a different computer","D":"Only threads can perform input and output"}', 'A',
     'Processes normally have separate address spaces. IPC provides controlled ways to exchange information, such as messages, pipes, or shared memory.', 'Interprocess Communication'),
    ('Two processes map the same shared-memory region and both modify a counter in it. What else is needed to prevent lost updates?',
     '{"A":"Identical process IDs","B":"An appropriate interprocess synchronization mechanism","C":"A different executable filename for each process","D":"A separate copy of the counter for every read"}', 'B',
     'Shared memory provides access to common data but does not make compound updates atomic. Processes need a suitable shared synchronization protocol.', 'Interprocess Communication'),
    ('Which description best fits message-passing IPC?',
     '{"A":"Each process directly edits every other process stack","B":"Processes must share one program counter","C":"Processes exchange information through send and receive operations","D":"Every message changes the receiver process ID"}', 'C',
     'Message passing exchanges information through communication operations rather than requiring processes to directly access the same application data region.', 'Interprocess Communication'),
    ('A process performs a blocking receive on an empty message queue. What normally happens until a message arrives or the operation is interrupted?',
     '{"A":"It repeatedly receives fabricated messages","B":"It must remain on the CPU continuously","C":"It terminates successfully","D":"It waits rather than continuing past the receive"}', 'D',
     'A blocking receive waits when no message is available. This differs from a nonblocking receive, which can return immediately with no message.', 'Interprocess Communication'),
    ('What does a traditional UNIX pipe provide to communicating processes?',
     '{"A":"A byte stream with a read end and a write end","B":"A shared CPU register set","C":"A separate CPU core for each byte","D":"A replacement for all file permissions"}', 'A',
     'A traditional pipe provides a byte stream between its write and read ends. Applications must define their own message framing if they need discrete records.', 'Interprocess Communication'),
    ('What makes sockets useful when two cooperating processes run on different computers?',
     '{"A":"Sockets require the processes to share physical RAM","B":"Sockets can provide communication endpoints across a network","C":"Sockets eliminate all possible communication failures","D":"Sockets force both processes to have the same process ID"}', 'B',
     'Sockets can connect processes across a network. Programs still need to handle protocol details and failures; shared physical memory is not required.', 'Interprocess Communication'),
    ('A bounded message queue is full. Under a blocking-send policy, what should a sender expect?',
     '{"A":"All existing messages are silently overwritten","B":"The receiver is automatically terminated","C":"The send waits for space to become available","D":"The queue grows without any bound"}', 'C',
     'Blocking send on a full bounded queue waits for capacity. This provides backpressure instead of requiring unbounded buffering.', 'Interprocess Communication'),
    ('Why might an application prefer copying requests into messages instead of giving another process writable access to a shared data structure?',
     '{"A":"Messages make every computation instantaneous","B":"Messages guarantee that receivers never fail","C":"Messages require all data to stay in CPU registers","D":"Messages can preserve address-space separation and define explicit communication boundaries"}', 'D',
     'Message exchange can keep internal data private and make the interface explicit. This can simplify isolation, although message processing still needs correct coordination.', 'Interprocess Communication'),
    ('What is a critical section in concurrent code?',
     '{"A":"A region accessing shared state that requires coordinated access","B":"Any function with more than ten lines","C":"A region that must always perform disk I/O","D":"Code that only the compiler can execute"}', 'A',
     'A critical section accesses shared state whose invariants can be violated by conflicting concurrent operations, so those operations require coordination.', 'Synchronization'),
    ('Two threads protect the same shared object with different, unrelated mutexes. Why can a race still occur?',
     '{"A":"Mutexes only work on single-core processors","B":"Acquiring one mutex does not exclude a thread holding the other mutex","C":"Mutexes automatically copy the protected object","D":"Using any two mutexes always terminates both threads"}', 'B',
     'Mutual exclusion requires a consistent protocol. Unrelated mutexes do not prevent the two threads from entering their conflicting sections together.', 'Synchronization'),
    ('A counting semaphore starts at 3. With no releases, how many successful acquire operations can complete before another acquire must wait?',
     '{"A":"Zero","B":"One","C":"Three","D":"An unlimited number"}', 'C',
     'Each successful acquire consumes one permit. Three initial permits allow three acquires before the count is exhausted.', 'Synchronization'),
    ('Why should a condition-variable wait normally be enclosed in a loop that checks the shared predicate?',
     '{"A":"Waiting guarantees the predicate will never change","B":"The loop prevents any thread from signaling","C":"Condition variables store every past signal forever","D":"A wakeup alone does not guarantee the predicate is true when the thread resumes"}', 'D',
     'Spurious wakeups or competing threads can leave the predicate false. Rechecking it while holding the associated mutex preserves correctness.', 'Synchronization'),
    ('What does a condition-variable wait normally do with its associated mutex while it waits?',
     '{"A":"Atomically releases it when waiting and reacquires it before returning","B":"Keeps it locked for the entire wait so no producer can enter","C":"Permanently destroys it","D":"Transfers ownership to every thread at once"}', 'A',
     'Releasing the mutex allows another thread to change the predicate. The wait returns with the mutex reacquired so the caller can safely recheck shared state.', 'Synchronization'),
    ('In a bounded-buffer design using semaphores, what should the empty-slot semaphore initially count?',
     '{"A":"The number of CPU cores","B":"The number of unused buffer slots","C":"The number of terminated producers","D":"The total number of messages ever produced"}', 'B',
     'The empty-slot semaphore tracks available capacity. For an initially empty buffer of capacity N, it starts at N.', 'Synchronization'),
    ('What distinguishes a spinlock wait from a blocking mutex wait?',
     '{"A":"A spinlock always uses less CPU time","B":"A spinlock requires a disk file","C":"A spinlock repeatedly checks availability while consuming CPU time","D":"A spinlock allows every contender into the critical section"}', 'C',
     'Spinning actively polls rather than sleeping. It can be appropriate for short waits in suitable environments but consumes CPU while waiting.', 'Synchronization'),
    ('What is the purpose of a barrier used by a fixed group of worker threads?',
     '{"A":"To give all workers the same stack","B":"To permanently stop every worker at startup","C":"To remove the need for all shared-data synchronization","D":"To hold workers at a phase boundary until all required participants arrive"}', 'D',
     'A barrier coordinates phases: participating workers wait until the required group reaches the barrier before proceeding.', 'Synchronization'),
    ('Which situation is a deadlock?',
     '{"A":"Two threads each wait for a lock held by the other, with neither able to release its lock","B":"A thread briefly waits for a busy CPU","C":"A thread finishes its work and releases its locks","D":"A scheduler switches from one ready thread to another"}', 'A',
     'The two threads form a circular wait and cannot progress under this locking protocol. Ordinary temporary waiting alone is not deadlock.', 'Deadlock'),
    ('Which set lists the four classic necessary conditions for resource deadlock?',
     '{"A":"Paging, caching, buffering, and spooling","B":"Mutual exclusion, hold and wait, no preemption, and circular wait","C":"Arrival, execution, completion, and termination","D":"Compilation, linking, loading, and execution"}', 'B',
     'The classic conditions are mutual exclusion, hold and wait, no preemption, and circular wait. Preventing any one of them prevents deadlock in this resource model.', 'Deadlock'),
    ('All threads acquire multiple locks in the same global order. Which deadlock condition does this rule prevent?',
     '{"A":"The existence of shared data","B":"The use of CPU time","C":"Circular wait","D":"All forms of waiting"}', 'C',
     'Consistent lock ordering prevents a cycle in which a thread holds a later lock while waiting for an earlier one. Threads may still wait temporarily.', 'Deadlock'),
    ('A process must obtain all required resources together before beginning, rather than retaining some while waiting for others. Which condition does this address?',
     '{"A":"The existence of virtual memory","B":"Process isolation","C":"Time slicing","D":"Hold and wait"}', 'D',
     'Obtaining all resources together prevents a process from holding a subset while waiting to acquire more, although it can reduce resource utilization.', 'Deadlock'),
    ('How does starvation differ from deadlock?',
     '{"A":"Starvation can indefinitely delay one participant while other participants continue making progress","B":"Starvation always requires a circular chain of locks","C":"Deadlock only occurs when all CPU cores are idle","D":"Starvation means every process has completed"}', 'A',
     'Starvation concerns indefinite postponement, often due to unfair allocation. Deadlocked participants cannot progress because of their dependency cycle or resource wait.', 'Deadlock'),
    ('What is livelock?',
     '{"A":"Every participant has terminated","B":"Participants keep changing state in response to each other without completing useful work","C":"A process runs without any other runnable process","D":"A blocked process sleeps until I/O completes"}', 'B',
     'In livelock, participants remain active but their reactions prevent useful progress, unlike blocked participants in a typical lock deadlock.', 'Deadlock'),
    ('In a resource-allocation graph where every resource type has exactly one instance, what does a directed cycle imply?',
     '{"A":"Every process has finished","B":"The system must have spare resources","C":"Deadlock exists","D":"No process is waiting"}', 'C',
     'With a single instance of each resource type, a cycle implies deadlock. With multiple instances, a cycle alone is not sufficient to establish deadlock.', 'Deadlock'),
    ('In deadlock avoidance, what does it mean for a resource-allocation state to be safe?',
     '{"A":"No process will ever request another resource","B":"Every resource is currently unallocated","C":"Every process must execute simultaneously","D":"There is an order in which all processes can finish given their declared maximum needs"}', 'D',
     'A safe state has a completion sequence that can satisfy declared maximum needs as resources are released. An unsafe state is not necessarily already deadlocked.', 'Deadlock'),
    ('What is the main role of a page table?',
     '{"A":"To map virtual pages to physical frames and record associated metadata","B":"To list only CPU scheduling priorities","C":"To store the source code of every process","D":"To replace every process stack"}', 'A',
     'Page-table entries describe virtual-to-physical mappings and may include presence, protection, reference, and modification information.', 'Memory Management'),
    ('With a page size of 1024 bytes, what are the virtual page number and offset for virtual byte address 2500?',
     '{"A":"Page 1, offset 1476","B":"Page 2, offset 452","C":"Page 2, offset 500","D":"Page 3, offset 452"}', 'B',
     'Integer division gives page number 2500 / 1024 = 2, and the remainder is 452. Page numbers here start at zero.', 'Memory Management'),
    ('What does a translation lookaside buffer (TLB) cache?',
     '{"A":"Only executable files from disk","B":"Only the contents of recently printed documents","C":"Recently used address translations","D":"The next question in a scheduling queue"}', 'C',
     'A TLB caches virtual-to-physical address translations, reducing the need to consult page tables for every memory access.', 'Memory Management'),
    ('A valid virtual page is not resident in physical memory when a process accesses it. What normally occurs in a demand-paged system?',
     '{"A":"The address automatically refers to physical frame zero","B":"The CPU ignores the instruction permanently","C":"The process is always terminated without OS involvement","D":"A page fault transfers control to the operating system to resolve the missing page"}', 'D',
     'A nonresident valid page causes a page fault. The OS can obtain the page, update the mapping, and allow the instruction to retry.', 'Memory Management'),
    ('A process needs 6000 bytes stored in pages of 4096 bytes. How much unused space is in its last allocated page?',
     '{"A":"2192 bytes","B":"1904 bytes","C":"4096 bytes","D":"6000 bytes"}', 'A',
     'Two pages provide 8192 bytes. The unused portion of the last page is 8192 minus 6000 = 2192 bytes, an example of internal fragmentation.', 'Memory Management'),
    ('Which situation illustrates external fragmentation with variable-size contiguous allocation?',
     '{"A":"Unused bytes at the end of one fixed-size page","B":"Enough total free memory exists, but it is split into holes too small for a requested contiguous block","C":"Every free byte lies in a single block large enough for the request","D":"A TLB contains a cached translation"}', 'B',
     'External fragmentation consists of separated free holes that cannot satisfy a contiguous allocation even when their total size is sufficient.', 'Memory Management'),
    ('Before reclaiming a dirty page frame whose modified contents must be preserved, what must the operating system arrange?',
     '{"A":"Discard its modifications without saving them","B":"Give every process write access to it","C":"Write the modified contents to appropriate backing storage","D":"Remove all other processes from memory"}', 'C',
     'A dirty page differs from its backing copy. Its changes must be written back before the frame is reused if those contents must be preserved.', 'Memory Management'),
    ('What best describes thrashing in a virtual-memory system?',
     '{"A":"Every requested page is already resident","B":"The CPU never needs an address translation","C":"A process uses only one memory address","D":"Frequent page faults and paging activity leave little time for useful execution"}', 'D',
     'Thrashing occurs when active working sets do not fit in available memory, causing excessive paging and poor useful throughput.', 'Memory Management')
) AS seed(prompt, options, answer, explanation, concept_name)
JOIN concepts c ON c.name = seed.concept_name;
